package com.zajel.app;

import android.app.*;import android.graphics.Color;import android.os.Bundle;import android.widget.*;import com.zajel.app.core.AppContainer;import com.zajel.app.domain.*;import java.util.*;
public final class ChannelsActivity extends Activity{LinearLayout root;AppContainer c;TextView status;public void onCreate(Bundle b){super.onCreate(b);c=((ZajelApplication)getApplication()).container();render();load();}void render(){root=new LinearLayout(this);root.setOrientation(LinearLayout.VERTICAL);root.setPadding(32,48,32,24);root.setBackgroundColor(Color.WHITE);setContentView(root);TextView h=new TextView(this);h.setText("Channels");h.setTextSize(28);root.addView(h);Button create=new Button(this);create.setText("Create channel");root.addView(create);create.setOnClickListener(v->{EditText e=new EditText(this);e.setHint("Channel name");new AlertDialog.Builder(this).setTitle("Create channel").setView(e).setPositiveButton("Create",(d,w)->c.channels.create(e.getText().toString(),"",false,new com.zajel.app.data.ChannelRepository.Callback<Channel>(){public void success(Channel x){load();}public void error(Exception z){status.setText(z.getMessage());}})).show();});status=new TextView(this);root.addView(status);}void load(){c.channels.publicChannels(new com.zajel.app.data.ChannelRepository.Callback<List<Channel>>(){public void success(List<Channel>x){runOnUiThread(()->{status.setText(x.isEmpty()?"No public channels":"Public channels");for(Channel n:x){Button b=new Button(ChannelsActivity.this);b.setText(n.title);root.addView(b);b.setOnClickListener(v->open(n));}});}public void error(Exception e){runOnUiThread(()->status.setText("Unable to load channels"));}});}void open(Channel n){EditText e=new EditText(this);e.setHint("Post");new AlertDialog.Builder(this).setTitle(n.title).setView(e).setPositiveButton("Publish",(d,w)->c.channels.publish(n.id,e.getText().toString(),new com.zajel.app.data.ChannelRepository.Callback<ChannelPost>(){public void success(ChannelPost p){}public void error(Exception z){}})).setNeutralButton("Follow",(d,w)->c.channels.follow(n.id,new com.zajel.app.data.ChannelRepository.Callback<Void>(){public void success(Void v){}public void error(Exception z){}})).show();}}
